WHO = {'tree': [('kidu', 109684), ('eincdeyeben', 109940), ('shacecldeki', 110196), ('vathldeki', 110451), ('aprilfools', 111411), ('ormaldoum', 0), ('zeldmeyeben', 0), ('aprildmicro', 112115)], 'column': [('vathldtem', 0), ('zenor', 0), ('shacesen', 109748), ('eincdgepy', 0), ('eincdeyeben', 0), ('vathleyeben', 110132), ('eincdmut', 110196), ('aprilfools', 0)], 'bridge': [('alphafoldmicro', 109940), ('eincdldmicro', 0), ('elndmdmicro', 0), ('alphafoldmicro', 111411), ('eincdldmicro', 111475), ('zeldmicro', 0), ('elndmdmicro', 0), ('eincdleyeben', 117170)], 'manor': [('vathlicro', 110132), ('eincdgepy', 111411), ('eincdeki', 0), ('psiloceyeben', 111923), ('vathldccum', 115186), ('vidmicro', 118577), ('eincdlsol', 120240), ('vathlicro', 0)], 'tower': [('psiloceyeben', 110451), ('vathldicro', 111155), ('einsof', 0), ('alphafoldmicro', 113842), ('vathlcldeki', 114034), ('vathldtem', 118641), ('vathldmut', 120431), ('psiloceyeben', 121902)], 'temple': [('renlo', 0), ('einsof', 112115), ('aprileyeben', 112115), ('aprileolum', 0), ('shacecldeki', 114290), ('qum', 0), ('psiloceyeben', 0), ('vathlcdsol', 118641)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW212(OracleReleaseRuntimeW244):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
